// Foundation react-intl message catalog — default locale (en) = source of truth.
//
// Flat, stable dotted message ids -> ICU messages. `MessageId` is derived from
// THIS map, so a component can only `formatMessage({ id })` an id that exists
// here (no arbitrary strings). Adding an id here forces every other locale
// (`zh-cn.ts`, `ja.ts`, `ko.ts`, typed `Record<MessageId, string>`) to fill it or
// fail typecheck — that is the completeness gate; the key-equivalence test is the
// CI backstop. Locales and per-language style: docs/frontend/i18n/README.md.
//
// This is the migration target for the homegrown typed catalogs: existing copy
// is carried over verbatim and reformatted to flat ICU ids (not re-authored).
// Vertical slice = the `common` namespace (from the #3874 `common` catalog).
// `fixtures.*` are non-user-facing; they exercise the ICU rails (placeholder /
// plural / number-currency / date) so contract tests pin the formatting layer
// from the foundation, before any real plural/currency copy is migrated.

