  "migration.error.entryCountLimitExceeded": "The workspace has too many files and folders to move. Ask the agent to delete folders it no longer needs, or to list them in .raftmigrateignore, then try again.",
  "migration.error.entryCountLimitExceededWithDetails": "The workspace has {count, number} files and folders; migration supports up to {limit, number}.{paths, select, none {} other { Most are in {paths}.}} Ask the agent to delete folders it no longer needs, or to list them in .raftmigrateignore, then try again.",
  "migration.error.workspaceAlreadyExists": "The target computer could not install the agent because that workspace already exists. Check which copy is current; move or back up the conflicting workspace, then try again. Raft will not delete it automatically.",
  "migration.error.workspaceCompleteOldCopy": "The target computer found a previously completed copy of this workspace and stopped before replacing it. Confirm which copy is current; move or back up the old copy, then try again. Raft will not delete it automatically.",
  "migration.error.workspaceAlreadyExistsAt": "A workspace already exists at {path} on the target computer, so the agent was not installed. Rename or move that folder — for example, appending .bak to its name is enough — then start the migration again. Check before you move it that this is not a copy you still need — Raft never deletes it, and moving it leaves it on that computer.",
  "migration.error.workspaceCompleteOldCopyAt": "A completed copy of this workspace from an earlier migration is at {path} on the target computer, so Raft stopped instead of replacing it. Rename or move that folder — for example, appending .old to its name is enough — then start the migration again. Check before you move it which copy is current — Raft never deletes it, and moving it leaves it on that computer.",
  "migration.error.controlManifestInvalid": "The source computer produced transfer metadata that the target computer could not verify. Update Raft Computer on both computers, then try again.",
