  "migration.error.computerOwnerDeleted": "This migration stopped because the owner of one of its computers deleted their Raft account. Move the agent to another computer.",
  "migration.error.targetComputerDetached": "This migration stopped because the target computer was detached before the agent could move onto it. The agent stays where it was; choose another computer.",
